private string BuildWeekDetailsXml(DataRow drw)
{
    StringBuilder sbXml = new StringBuilder();
    sbXml.Append("<Root>");
    for (int intWeekIndex = 0; intWeekIndex <= Global.Variable.MaxWeekOfYear; intWeekIndex++)
    {
        string strCol = "Week_" + intWeekIndex.ToString();
        if (!dtbData.Columns.Contains(strCol))
            continue;
        string strValue = drw[strCol].ToString().Trim();
        if (strValue == "")
            continue;
        int intQty;
        if (strValue.ToUpper() == "KT")
            intQty = 0;
        else if (!int.TryParse(strValue, out intQty))
            continue;
        sbXml.AppendFormat("<Item Week=\"{0}\" Qty=\"{1}\" />", intWeekIndex, intQty);
    }
    sbXml.Append("</Root>");
    return sbXml.ToString();
}
private bool SaveWeekDetailPlanData()
{
    DataRow[] rows = dtbData.Select("IsEditWeek = 1 And ClassSubjectID is not null And ClassSubjectID <> ''");
    if (rows.Length <= 0)
        return true;
    SimsObject.SIM_WeekDetailPlan obj = new SimsObject.SIM_WeekDetailPlan();
    if (!obj.BeginTransaction())
    {
        ErrorManager.Error("Không kết nối được cơ sở dữ liệu!");
        return false;
    }
    try
    {
        foreach (DataRow drw in rows)
        {
            long lngClassSubjectID = Convert.ToInt64(drw["ClassSubjectID"]);
            int intSaveYearID = intYearID;
            if (drw["YearID"] != DBNull.Value && drw["YearID"].ToString() != "")
                intSaveYearID = Convert.ToInt32(drw["YearID"]);
            string strXml = BuildWeekDetailsXml(drw);
            SimsObject.SIM_WeekDetailPlan item = new SimsObject.SIM_WeekDetailPlan();
            item.IDB = obj.IDB;
            if (!item.SaveForClassSubject(lngClassSubjectID, intSaveYearID, false, UserSession.Username, strXml))
            {
                if (item.ErrorException != null)
                    ErrorManager.Error(item.ErrorException.Message);
                else
                    ErrorManager.Error("Lưu kế hoạch tuần bị lỗi!");
                obj.RollBackTransaction();
                return false;
            }
            drw["IsEditWeek"] = false;
        }
        obj.CommitTransaction();
        return true;
    }
    catch (Exception objExc)
    {
        obj.RollBackTransaction();
        ErrorManager.Error("Việc cập nhật kế hoạch tuần bị lỗi! Vui lòng kiểm tra lại dữ liệu!");
        SystemService.SYS_ErrorLogService.Write(Enums.ActionType.Edit, "frmWeekTeachingPlan2->SaveWeekDetailPlanData", objExc, 0);
        return false;
    }
}
